#!/usr/bin/env bash
# Generated by kubegen from examples/kind.yaml - re-generate instead of editing.
# Creates the kind cluster "dev-local".
set -euo pipefail

die() { echo "error: $*" >&2; exit 1; }

# Required tools
missing=0
need() {
  command -v "$1" >/dev/null 2>&1 && return
  echo "error: required tool '$1' is not installed or not in PATH" >&2
  echo "       install it from: $2" >&2
  missing=1
}
need docker https://docs.docker.com/get-docker/
need kind 'https://kind.sigs.k8s.io/docs/user/quick-start/#installation'
need kubectl https://kubernetes.io/docs/tasks/tools/
[ "$missing" -eq 0 ] || exit 127

echo '==> Checking Docker'
docker info >/dev/null 2>&1 || die "Docker is installed but the daemon is not running"

echo '==> Creating kind cluster dev-local'
CONFIG_FILE="$(mktemp)"
trap 'rm -f "$CONFIG_FILE"' EXIT
cat > "$CONFIG_FILE" <<'KUBEGEN_EOF'
kind: Cluster
apiVersion: kind.x-k8s.io/v1alpha4
networking:
  podSubnet: "10.244.0.0/16"
  serviceSubnet: "10.96.0.0/12"
nodes:
  - role: control-plane
    labels:
      ingress-ready: "true"
    extraPortMappings:
      - containerPort: 80
        hostPort: 80
        protocol: TCP
      - containerPort: 443
        hostPort: 443
        protocol: TCP
      - containerPort: 30080
        hostPort: 8080
  - role: worker
  - role: worker
KUBEGEN_EOF
kind create cluster --name dev-local \
  --config "$CONFIG_FILE" \
  --image kindest/node:v1.33.1 \
  --wait 180s

echo '==> Verifying access to dev-local'
kubectl get nodes -o wide

echo "Cluster dev-local is ready."
